import weakref, collections

class Mediator:
    def __init__(self): self._handlers = collections.defaultdict(list)
    def subscribe(self, event, handler, *, weak=False):
        self._handlers[event].append(weakref.WeakMethod(handler) if weak else handler)
    def notify(self, event, payload=None):
        for ref in list(self._handlers[event]):
            handler = ref() if isinstance(ref, weakref.WeakMethod) else ref
            if handler: handler(payload)

